"""The public domain catalog; no transport, MCP runtime or host initialization."""

import difflib
from dataclasses import dataclass
from typing import Any

from bitwig_agent import schema


@dataclass(frozen=True)
class ToolSpec:
    model: type[schema.StatusArgs]
    description: str
    read_only: bool
    examples: tuple[dict[str, Any], ...]

    def describe(self) -> dict[str, Any]:
        return {"description": self.description, "readOnly": self.read_only,
                "inputSchema": self.model.model_json_schema(), "examples": list(self.examples)}


# Example UUIDs are placeholders: discover real targets with tracks.list first.
TRACK = "12345678-1234-1234-1234-123456789abc"
TARGET = {"trackId": TRACK, "deviceIndex": 0, "expectedDeviceName": "Poly Grid"}
LAYER_PARENT = {"trackId": TRACK, "deviceIndex": 0, "expectedDeviceName": "Instrument Layer"}
LAYER_TARGET = {"parent": LAYER_PARENT, "layerId": "abcdef01-2345-6789-abcd-0123456789ab",
                "childDeviceIndex": 0, "expectedChildDeviceName": "Polymer",
                "discoveryToken": "from-devices.layers.list"}
CLIP = {"trackId": TRACK, "slotIndex": 0}
NOTE_WINDOW = {**CLIP, "channel": 0, "stepSizeBeats": 0.25, "startStep": 0,
               "steps": 16, "pitchStart": 0, "pitchCount": 128}


DIFF = 'Result is a diff, absent when empty: modulesAdded (full rows with ports, wire them at once), modulesRemoved, modulesMoved, modulesRenamed, connectionsChanged (any cable changed anywhere, including native repair), moduleCount; graphComplete=false with graphUnsupported if coverage was partial. graph="full" returns the whole bounded graph instead.'
SAFE = 'Needs a stopped, nonrecording, nonautomation state, a complete bounded graph of at most 1024 modules, and the explicit device target (trackId from tracks.list; deviceIndex and exact expectedDeviceName from devices.list). '
UNK = 'Never retry an unknown outcome: inspect with grid.get. A native setter/callback failure quarantines further topology edits until Bitwig restarts.'


# Composed in Python from host methods; never sent to the host as one request.
CLIENT_SIDE = frozenset({"grid.apply", "grid.render", "grid.describe", "audio.route", "audio.capture", "audio.analyze"})


def tool(model, description, read_only, *examples):
    return ToolSpec(model, description, read_only, examples or ({},))


